[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$JobRoot,
    [Parameter(Mandatory=$true)][string]$AttemptId,
    [string]$RepositoryRoot
)
$ErrorActionPreference='Stop';if(-not $RepositoryRoot){$RepositoryRoot=Split-Path -Parent $PSScriptRoot};$RepositoryRoot=[IO.Path]::GetFullPath($RepositoryRoot);$JobRoot=[IO.Path]::GetFullPath($JobRoot);$attemptRoot=Join-Path $JobRoot (Join-Path 'output' $AttemptId);if(Test-Path $attemptRoot){throw "Attempt exists: $attemptRoot"}
$source=Join-Path $RepositoryRoot 'src\fg_conv\rtx_custom_bot0_oracle.cpp';$baseSource=Join-Path $RepositoryRoot 'src\fg_conv\rtx_oracle.cpp';$contract=Join-Path $RepositoryRoot 'src\fg_conv\custom_bot0_contract.h';$module=Join-Path $JobRoot 'inputs\cu-module-000058.bin';$weights=Join-Path $JobRoot 'inputs\default-token-000150-post-eval0.bin';$bias=Join-Path $JobRoot 'inputs\default-token-000152-post-eval0.bin';$manifest=Join-Path $JobRoot 'inputs\runtime-default-buffers-post-evaluate-0.manifest.json'
foreach($required in @($source,$baseSource,$contract,$module,$weights,$bias,$manifest)){if(-not(Test-Path $required -PathType Leaf)){throw "Missing input: $required"}}
if((Get-FileHash $module -Algorithm SHA256).Hash -ne '3ACB96881F20A50E575E2B2959F0AA433E03E3DA20FBF624AE6BB183D77A3E48'){throw 'Module mismatch'};if((Get-FileHash $weights -Algorithm SHA256).Hash -ne '6B59F16F1BE43617EBF0C94FF29CF7C8B7A2F2C7B7BFB41DF8F9EDE585E70684'){throw 'Weight mismatch'};if((Get-FileHash $bias -Algorithm SHA256).Hash -ne 'C3E301DF2E15C48E0C2FB35FC636B944653C6F91071A101D71B256B740224D29'){throw 'Bias mismatch'};if((Get-FileHash $manifest -Algorithm SHA256).Hash -ne '2A1179D4A25BE030F772CD90CA7D017ED6EAC9291917F7D43EA9B0CD5AC6A294'){throw 'Manifest mismatch'}
$cudaPath=$env:CUDA_PATH;if(-not $cudaPath){$cudaPath='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$installation=& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vcvars=Join-Path $installation 'VC\Auxiliary\Build\vcvars64.bat';$buildRoot=Join-Path $attemptRoot 'build';New-Item -ItemType Directory -Path $buildRoot|Out-Null;$binary=Join-Path $buildRoot 'fg-custom-bot0-rtx.exe';$object=Join-Path $buildRoot 'fg-custom-bot0-rtx.obj';$compileLog=Join-Path $buildRoot 'compile.log';$compileCommand='"{0}" >nul && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link.exe /nologo /OUT:"{5}" "{2}" "{6}" bcrypt.lib >>"{4}" 2>&1' -f $vcvars,(Join-Path $cudaPath 'include'),$object,$source,$compileLog,$binary,(Join-Path $cudaPath 'lib\x64\cuda.lib');& $env:ComSpec /d /s /c $compileCommand;if($LASTEXITCODE -ne 0){throw "Build failed: $compileLog"}
$receipts=@();foreach($poison in @('a5','5a')){foreach($ordinal in @('a','b')){$runId="bot0-poison-$poison-process-$ordinal";$runRoot=Join-Path $attemptRoot $runId;New-Item -ItemType Directory -Path $runRoot|Out-Null;$process=Start-Process -FilePath $binary -ArgumentList @($module,$weights,$bias,$runRoot,$runId,$poison) -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $runRoot 'stdout.log') -RedirectStandardError (Join-Path $runRoot 'stderr.log');if($process.ExitCode -ne 0){throw "Run failed: $runId"};$receipts+=Get-Content (Join-Path $runRoot 'run-receipt.json') -Raw|ConvertFrom-Json}}
$hashes=@($receipts|ForEach-Object{$_.output_sha256}|Sort-Object -Unique);$pids=@($receipts|ForEach-Object{$_.process_id}|Sort-Object -Unique);if($hashes.Count -ne 1 -or $pids.Count -ne 4){throw 'Repeat/poison gate failed'}
$receipt=[ordered]@{schema='neuralstudio.fg.custom-bot0-rig.v1';job_id=(Split-Path -Leaf $JobRoot);attempt_id=$AttemptId;gpu=(& nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits|Select-Object -First 1).Trim();cuda_toolkit=(&(Join-Path $cudaPath 'bin\nvcc.exe') --version|Select-Object -Last 1).Trim();module_sha256=(Get-FileHash $module -Algorithm SHA256).Hash.ToLowerInvariant();weight_sha256=(Get-FileHash $weights -Algorithm SHA256).Hash.ToLowerInvariant();bias_sha256=(Get-FileHash $bias -Algorithm SHA256).Hash.ToLowerInvariant();manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash.ToLowerInvariant();source_sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();base_source_sha256=(Get-FileHash $baseSource -Algorithm SHA256).Hash.ToLowerInvariant();contract_sha256=(Get-FileHash $contract -Algorithm SHA256).Hash.ToLowerInvariant();binary_sha256=(Get-FileHash $binary -Algorithm SHA256).Hash.ToLowerInvariant();fresh_process_count=$pids.Count;two_poison_output_sha256=$hashes[0];full_write_coverage_from_two_poison_invariance=$true;address_fields_recorded=$false;result='pass'};$utf8NoBom=New-Object System.Text.UTF8Encoding($false);$receiptPath=Join-Path $attemptRoot 'rig-receipt.json';[IO.File]::WriteAllText($receiptPath,(($receipt|ConvertTo-Json -Depth 6)+"`n"),$utf8NoBom);$receiptHash=(Get-FileHash $receiptPath -Algorithm SHA256).Hash.ToLowerInvariant();[IO.File]::WriteAllText((Join-Path $attemptRoot 'rig-receipt.sha256'),($receiptHash+"  rig-receipt.json`n"),$utf8NoBom);Write-Host "attempt_root=$attemptRoot";Write-Host "output_sha256=$($hashes[0])";Write-Host "rig_receipt_sha256=$receiptHash";Write-Host 'result=pass'

